fn swap_record(seed: u64) -> value: SwapRecord pure {
  let words = array_filled::<u64, 32>(value: 0_u64);
  for (index in 0_u64..32_u64) {
    set words[index] = seed +wrap index;
  }
  return SwapRecord(words: words);
}

fn swap_record_check(value: &SwapRecord, seed: u64) -> failures: u64 reads(value) {
  let failures = 0_u64;
  for (index in 0_u64..32_u64) {
    let expected = seed +wrap index;
    if value^.words[index] != expected {
      set failures = failures +wrap 1_u64;
    }
  }
  return failures;
}

fn swap_focused(fault: u64) -> failures: u64 pure {
  doc "Checks every word of each returned and surviving owner against separately written seeds. Removes a non-last interior, last, first and singleton slot. Fault1 corrupts the returned last word; fault2 corrupts a replacement word via ordinary remove/append; fault3 reorders surviving owners while preserving their multiset.";
