  let empty_two = SwapEmpty();
  let empty_second = grow_vector_append::<SwapEmpty, 2>(values: &empty_values, value: move empty_two);
  let empty_nonlast = grow_vector_swap_remove::<SwapEmpty, 2>(values: &empty_values, index: 0_u64);
  let empty_singleton = grow_vector_swap_remove::<SwapEmpty, 2>(values: &empty_values, index: 0_u64);
