    let ticket_first = grow_vector_append::<Ticket, 2>(values: &tickets, value: move ticket_one);
    let ticket_two = ticket_new(id: 22_u64);
    let ticket_second = grow_vector_append::<Ticket, 2>(values: &tickets, value: move ticket_two);
    let ticket_last = grow_vector_swap_remove::<Ticket, 2>(values: &tickets, index: 1_u64);
